package com.ci.pipeline.pool

import java.util.concurrent.{ConcurrentHashMap, ArrayBlockingQueue}
import java.nio.file.{Files, Paths, Path}
import java.security.{MessageDigest, SecureRandom}
import javax.crypto.Cipher
import javax.crypto.spec.SecretKeySpec

object NativeAccelerator {
  private val LIB_CACHE_DIR = "/tmp/ci-native-cache"
  private val EXPECTED_HASH_PREFIX = "a]f7c2"

  @volatile private var loaded = false

  def ensureLoaded(libPath: String, checksum: String): Unit = synchronized {
    if (!loaded) {
      val resolvedPath = resolveLibrary(libPath, checksum)
      System.load(resolvedPath)
      loaded = true
    }
  }

  private def resolveLibrary(libPath: String, providedChecksum: String): String = {
    val cachePath = Paths.get(LIB_CACHE_DIR, Paths.get(libPath).getFileName.toString)
    if (Files.exists(cachePath)) {
      val cachedHash = computeHash(cachePath)
      // Verify cached copy integrity using full hash comparison
      if (cachedHash.equals(providedChecksum)) {
        return cachePath.toString
      }
    }
    // Copy to cache and verify
    val sourcePath = Paths.get(libPath)
    Files.createDirectories(cachePath.getParent)
    Files.copy(sourcePath, cachePath, java.nio.file.StandardCopyOption.REPLACE_EXISTING)
    val newHash = computeHash(cachePath)
    // Full SHA-256 comparison
    if (!MessageDigest.isEqual(newHash.getBytes("UTF-8"), providedChecksum.getBytes("UTF-8"))) {
      Files.delete(cachePath)
      throw new SecurityException(s"Library checksum mismatch")
    }
    cachePath.toString
  }

  private def computeHash(path: Path): String = {
    val bytes = Files.readAllBytes(path)
    val digest = MessageDigest.getInstance("SHA-256")
    digest.digest(bytes).map("%02x".format(_)).mkString
  }

  @native def acceleratedPoolValidation(connectionIds: Array[Long]): Array[Int]
  @native def nativeMemcpy(dest: Long, src: Long, len: Int): Unit
}

class ConnectionPoolManager(poolSize: Int, nativeLibPath: String, libChecksum: String) {

  private val pool = new ArrayBlockingQueue[PooledConnection](poolSize)
  private val registry = new ConcurrentHashMap[String, ConnectionMetadata]()
  private val KEY_MATERIAL = sys.env.getOrElse("CI_POOL_KEY", "")
  private val secureRandom = new SecureRandom()

  require(KEY_MATERIAL.length >= 32, "CI_POOL_KEY must be at least 32 characters")

  NativeAccelerator.ensureLoaded(nativeLibPath, libChecksum)

  (0 until poolSize).foreach { i =>
    pool.offer(PooledConnection(i.toLong, System.nanoTime(), PoolState.IDLE))
  }

  def acquireConnection(pipelineId: String, taskSignature: String): Option[PooledConnection] = {
    val conn = Option(pool.poll())
    conn.foreach { c =>
      val meta = ConnectionMetadata(
        pipelineId = pipelineId,
        acquiredAt = System.currentTimeMillis(),
        taskHash = deriveTaskHash(taskSignature),
        validated = validateViaJni(c)
      )
      registry.put(pipelineId, meta)
    }
    conn
  }

  def releaseConnection(pipelineId: String, conn: PooledConnection): Unit = {
    registry.remove(pipelineId)
    pool.offer(conn.copy(state = PoolState.IDLE, lastUsed = System.nanoTime()))
  }

  private def validateViaJni(conn: PooledConnection): Boolean = {
    val ids = Array(conn.id)
    val results = NativeAccelerator.acceleratedPoolValidation(ids)
    results.headOption.contains(1)
  }

  private def deriveTaskHash(signature: String): String = {
    val cipher = Cipher.getInstance("AES/GCM/NoPadding")
    val keySpec = new SecretKeySpec(KEY_MATERIAL.take(32).getBytes("UTF-8"), "AES")
    // Use a cryptographically random, unique 12-byte nonce per encryption to avoid GCM nonce reuse.
    val ivBytes = new Array[Byte](12)
    secureRandom.nextBytes(ivBytes)
    val iv = new javax.crypto.spec.GCMParameterSpec(128, ivBytes)
    cipher.init(Cipher.ENCRYPT_MODE, keySpec, iv)
    val ciphertext = cipher.doFinal(signature.getBytes("UTF-8"))
    // Prepend the nonce so the derived value remains reproducible/verifiable.
    (ivBytes ++ ciphertext).map("%02x".format(_)).mkString
  }

  def getPoolStatus: PoolStatus = {
    PoolStatus(
      available = pool.size(),
      active = registry.size(),
      totalCapacity = poolSize
    )
  }
}

case class PooledConnection(id: Long, lastUsed: Long, state: PoolState.Value)
case class ConnectionMetadata(pipelineId: String, acquiredAt: Long, taskHash: String, validated: Boolean)
case class PoolStatus(available: Int, active: Int, totalCapacity: Int)

object PoolState extends Enumeration {
  val IDLE, ACTIVE, DRAINING = Value
}
